#include <bits/stdc++.h>
using namespace std;

struct Orient {
    vector<pair<int,int>> cells;
    int w, h;
    int r, f;
};

vector<Orient> getOrients(const vector<pair<int,int>>& cells) {
    vector<Orient> res;
    set<vector<pair<int,int>>> seen;
    for (int f = 0; f < 2; f++) {
        for (int r = 0; r < 4; r++) {
            vector<pair<int,int>> tr;
            for (auto [x, y] : cells) {
                int tx = x, ty = y;
                if (f) tx = -tx;
                for (int rr = 0; rr < r; rr++) {
                    int nx = ty, ny = -tx;
                    tx = nx; ty = ny;
                }
                tr.push_back({tx, ty});
            }
            int minx = INT_MAX, miny = INT_MAX;
            for (auto [x, y] : tr) { minx = min(minx, x); miny = min(miny, y); }
            for (auto& [x, y] : tr) { x -= minx; y -= miny; }
            sort(tr.begin(), tr.end());
            if (seen.insert(tr).second) {
                int mx = 0, my = 0;
                for (auto [x, y] : tr) { mx = max(mx, x); my = max(my, y); }
                res.push_back({tr, mx+1, my+1, r, f});
            }
        }
    }
    return res;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> ksz(n);
    vector<vector<pair<int,int>>> raw(n);
    int totalCells = 0;
    for (int i = 0; i < n; i++) {
        cin >> ksz[i];
        raw[i].resize(ksz[i]);
        for (int j = 0; j < ksz[i]; j++) cin >> raw[i][j].first >> raw[i][j].second;
        totalCells += ksz[i];
    }

    vector<vector<Orient>> allOr(n);
    for (int i = 0; i < n; i++) allOr[i] = getOrients(raw[i]);

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){
        if (ksz[a] != ksz[b]) return ksz[a] > ksz[b];
        return allOr[a].size() < allOr[b].size();
    });

    int bestArea = INT_MAX;
    int bestW = 0, bestH = 0;
    vector<int> bestX(n), bestY(n), bestR(n), bestF(n);

    int sqrtA = max(1, (int)ceil(sqrt((double)totalCells)));

    vector<int> cands;
    for (int w = max(1, sqrtA - 10); w <= sqrtA + 100; w++) cands.push_back(w);
    for (int w = sqrtA + 110; w <= min(totalCells, sqrtA * 4); w += 20) cands.push_back(w);
    // fallback: very wide
    cands.push_back(totalCells);

    auto t0 = chrono::steady_clock::now();

    for (int W : cands) {
        auto now = chrono::steady_clock::now();
        if (chrono::duration_cast<chrono::milliseconds>(now - t0).count() > 8500) break;

        int Hmax = totalCells / W + n * 11 + 20;
        // Use unordered_set for grid
        unordered_set<long long> occ;
        auto key = [&](int x, int y) -> long long { return (long long)x * 200000 + y; };

        vector<int> height(W, 0);
        vector<int> px(n), py(n), pr(n), pf(n);
        bool valid = true;
        int curH = 0;

        for (int idx = 0; idx < n; idx++) {
            int i = order[idx];
            int bestScore = INT_MAX;
            int bx=-1, by=-1, boi=-1;

            for (int oi = 0; oi < (int)allOr[i].size(); oi++) {
                auto& o = allOr[i][oi];
                if (o.w > W) continue;
                for (int x = 0; x <= W - o.w; x++) {
                    int minY = 0;
                    for (auto [cx, cy] : o.cells) minY = max(minY, height[x+cx] - cy);
                    if (minY < 0) minY = 0;
                    for (int y = minY; y <= minY + 30 && y + o.h <= Hmax; y++) {
                        bool ok = true;
                        for (auto [cx, cy] : o.cells) {
                            if (occ.count(key(x+cx, y+cy))) { ok = false; break; }
                        }
                        if (ok) {
                            int mh = max(curH, y + o.h);
                            int sc = mh * 100000 + y * 1000 + x;
                            if (sc < bestScore) { bestScore = sc; bx = x; by = y; boi = oi; }
                            break;
                        }
                    }
                    if (bestScore <= curH * 100000 + 1000) break;
                }
            }
            if (boi < 0) { valid = false; break; }
            px[i] = bx; py[i] = by; pr[i] = allOr[i][boi].r; pf[i] = allOr[i][boi].f;
            for (auto [cx, cy] : allOr[i][boi].cells) {
                occ.insert(key(bx+cx, by+cy));
                height[bx+cx] = max(height[bx+cx], by+cy+1);
                curH = max(curH, by+cy+1);
            }
        }
        if (!valid) continue;
        int H = curH;
        int area = W * H;
        if (area < bestArea || (area == bestArea && (H < bestH || (H == bestH && W < bestW)))) {
            bestArea = area; bestW = W; bestH = H;
            bestX = px; bestY = py; bestR = pr; bestF = pf;
        }
    }

    if (bestArea == INT_MAX) {
        // Emergency: place each piece in a row
        bestW = 10; bestH = totalCells;
        int cy = 0;
        for (int i = 0; i < n; i++) {
            bestX[i] = 0; bestY[i] = cy; bestR[i] = 0; bestF[i] = 0;
            cy += 11;
        }
        bestH = cy;
    }

    cout << bestW << " " << bestH << "\n";
    for (int i = 0; i < n; i++) cout << bestX[i] << " " << bestY[i] << " " << bestR[i] << " " << bestF[i] << "\n";
}
